fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left + right reconstructs a
    // - if n > 1 then both parts are strictly shorter than n
    //
    // For n <= 1, any split works; use (a, empty).
    // For n >= 2, split at n/2, which guarantees 1 <= mid <= n-1.
    let mid = if n > 1 { n / 2 } else { n };

    let mut right = a;
    let left = right.split_off(mid); // left gets elements [mid..], right keeps [0..mid)
    // We want (first_part, second_part) such that first + second == original.
    // After split_off: right == prefix, left == suffix.
    (right, left)
}